import {stableScreenshot} from '../../engine/capture-stability.mjs';
import assert from'node:assert/strict';import path from'node:path';import{readFile,writeFile}from'node:fs/promises';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{visualScore}from'../../engine/verify.mjs';import{PNG}from'pngjs';
const root=path.resolve('artifacts/platform/events-heldout'),source='http://127.0.0.1:9440',cases=[];let server,browser;
try{server=await serveStatic(path.join(root,'pagination-project/output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390])for(const number of [1,2]){const pair=[];for(const kind of ['source','export']){const page=await browser.newPage({viewport:{width,height:1000},reducedMotion:'reduce'}),sourceURL=source+'/events/?tribe-bar-date=2028-01-01&tribe_paged='+number,url=kind==='source'?sourceURL:server.url+'/events/list/?calendar-date=2028-01-01&calendar-page='+number;const sourceHTML=await readFile(path.join(root,`list-config-source-page-${number}.html`),'utf8');let blocked=0;await page.route('**/*',r=>{const request=r.request();if(request.method()!=='GET'||new URL(request.url()).origin!==(kind==='source'?source:server.url)){blocked++;return r.abort();}if(kind==='source'&&request.url()===sourceURL)return r.fulfill({contentType:'text/html; charset=utf-8',body:sourceHTML});return r.continue();});assert.equal((await page.goto(url,{waitUntil:'networkidle'})).status(),200);if(kind==='export')await page.waitForFunction(()=>document.querySelector('[data-calendar-page]'));await page.evaluate(()=>document.fonts.ready);const file=path.join(root,`pagination-${kind}-${number}-${width}.png`);const stable=await stableScreenshot(page,{fullPage:true,animations:'disabled'}).catch(async error=>{for(const [i,buffer]of (error.samples||[]).entries())await writeFile(file.replace('.png',`-unstable-${i+1}.png`),buffer);throw error;});await writeFile(file,stable.buffer);for(const [i,buffer]of stable.samples.entries())await writeFile(file.replace('.png',`-sample-${i+1}.png`),buffer);const measurement=await page.evaluate(()=>{const box=selector=>{const e=document.querySelector(selector);if(!e)return null;const b=e.getBoundingClientRect();return{x:b.x,y:b.y,width:b.width,height:b.height};};const arrow=document.querySelector('.tribe-events-c-subscribe-dropdown__button-icon');const arrowStyle=arrow?getComputedStyle(arrow):null;return{arrow:arrow?{box:box('.tribe-events-c-subscribe-dropdown__button-icon'),transform:arrowStyle.transform,transition:arrowStyle.transition,animation:arrowStyle.animation}:null,documentHeight:document.documentElement.scrollHeight,root:box('.tribe-events-view'),heading:box('.tribe-events-c-top-bar'),list:box('.tribe-events-calendar-list'),nav:box('.tribe-events-c-nav'),status:document.querySelector('[role=status]')?.textContent};});if(kind==='export')assert.equal(blocked,0,'Export attempted a nonlocal request');pair.push({kind,file,captures:stable.captures,measurement,blockedRequests:blocked});await page.close();}const a=await readFile(pair[0].file),b=await readFile(pair[1].file),ap=PNG.sync.read(a),bp=PNG.sync.read(b);cases.push({width,number,pair,dimensions:{source:[ap.width,ap.height],export:[bp.width,bp.height]},pixelSimilarity:ap.width===bp.width&&ap.height===bp.height?visualScore(a,b):null});}

 await writeFile(path.join(root,'pagination-visual-check.json'),JSON.stringify({scope:'Full-page saved installed-source versus native-export paginated list screenshots; no source interactions or submissions',cases},null,2)+'\n');console.log(JSON.stringify(cases.map(c=>({width:c.width,number:c.number,dimensions:c.dimensions,pixelSimilarity:c.pixelSimilarity,measurements:c.pair.map(p=>p.measurement)}))));
 for(const c of cases){assert.deepEqual(c.dimensions.source,c.dimensions.export);assert.equal(c.pixelSimilarity,1,`Page ${c.number} at ${c.width}px differs`);}
}finally{await browser?.close();await server?.close();}
